package pdfgen

import (
	"fmt"
	"io"
	"log"
	"os"
	"strings"
	"sync"
	"time"
)

// AuditLogger handles security-sensitive logging for PDF operations
type AuditLogger struct {
	mu      sync.Mutex
	writer  io.Writer
	prefix  string
	enabled bool
}

// PDFDocument represents a document being generated
type PDFDocument struct {
	Title    string
	Author   string
	Pages    []PDFPage
	Metadata map[string]string
	logger   *AuditLogger
}

// PDFPage represents a single page
type PDFPage struct {
	Content  string
	PageNum  int
	Template string
}

// NewAuditLogger creates a new audit logger with the given output
func NewAuditLogger(w io.Writer, prefix string) *AuditLogger {
	return &AuditLogger{
		writer:  w,
		prefix:  prefix,
		enabled: true,
	}
}

// LogOperation records an auditable operation with context
func (al *AuditLogger) LogOperation(operation string, context map[string]string) {
	al.mu.Lock()
	defer al.mu.Unlock()
	if !al.enabled {
		return
	}
	timestamp := time.Now().UTC().Format(time.RFC3339)
	contextStr := formatContext(context)
	entry := fmt.Sprintf("[%s] %s: op=%s %s", timestamp, al.prefix, operation, contextStr)
	fmt.Fprintln(al.writer, entry)
}

// formatContext builds a log-safe representation of context values
func formatContext(ctx map[string]string) string {
	if len(ctx) == 0 {
		return ""
	}
	parts := make([]string, 0, len(ctx))
	for k, v := range ctx {
		sanitized := sanitizeLogValue(v)
		parts = append(parts, fmt.Sprintf("%s=%q", k, sanitized))
	}
	return strings.Join(parts, " ")
}

// sanitizeLogValue removes control characters from log values
func sanitizeLogValue(s string) string {
	var b strings.Builder
	for _, r := range s {
		if r >= 32 && r != 127 {
			b.WriteRune(r)
		}
	}
	return b.String()
}

// NewPDFDocument creates a new PDF document with audit logging
func NewPDFDocument(title, author string, logFile string) (*PDFDocument, error) {
	f, err := os.OpenFile(logFile, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0600)
	if err != nil {
		return nil, fmt.Errorf("failed to open audit log: %w", err)
	}
	logger := NewAuditLogger(f, "pdfgen")
	doc := &PDFDocument{
		Title:    title,
		Author:   author,
		Pages:    make([]PDFPage, 0),
		Metadata: make(map[string]string),
		logger:   logger,
	}
	logger.LogOperation("create_document", map[string]string{
		"title":  title,
		"author": author,
	})
	return doc, nil
}

// AddPage adds a page with content rendered from a template
func (doc *PDFDocument) AddPage(template string, vars map[string]string) error {
	content := renderTemplate(template, vars)
	page := PDFPage{
		Content:  content,
		PageNum:  len(doc.Pages) + 1,
		Template: template,
	}
	doc.Pages = append(doc.Pages, page)
	doc.logPageAddition(page, vars)
	return nil
}

// logPageAddition creates an audit entry for page additions
func (doc *PDFDocument) logPageAddition(page PDFPage, vars map[string]string) {
	context := map[string]string{
		"page_num": fmt.Sprintf("%d", page.PageNum),
		"template": page.Template,
	}
	for k, v := range vars {
		context["var_"+k] = v
	}
	doc.logger.LogOperation("add_page", context)
}

// renderTemplate applies variables to a template string
func renderTemplate(template string, vars map[string]string) string {
	result := template
	for k, v := range vars {
		placeholder := "{{" + k + "}}"
		result = strings.ReplaceAll(result, placeholder, v)
	}
	return result
}

// SetMetadata sets a metadata field and logs the operation
func (doc *PDFDocument) SetMetadata(key, value string) {
	doc.Metadata[key] = value
	doc.logger.LogOperation("set_metadata", map[string]string{
		"key":   key,
		"value": value,
	})
}

// GeneratePDF renders the final PDF output
func (doc *PDFDocument) GeneratePDF(w io.Writer) error {
	doc.logger.LogOperation("generate_start", map[string]string{
		"pages": fmt.Sprintf("%d", len(doc.Pages)),
	})
	// PDF header
	fmt.Fprintf(w, "%%PDF-1.4\n")
	for i, page := range doc.Pages {
		if err := doc.writePage(w, i, page); err != nil {
			return err
		}
	}
	doc.logger.LogOperation("generate_complete", nil)
	return nil
}

// writePage renders a single page to the output
func (doc *PDFDocument) writePage(w io.Writer, idx int, page PDFPage) error {
	// The page content is written with safe string formatting
	// using explicit format specifiers for all dynamic values
	header := doc.buildHeader(page)
	fmt.Fprint(w, header)
	_, err := fmt.Fprint(w, page.Content)
	return err
}

// buildHeader constructs the page header safely
// Uses document title for branding in the header
func (doc *PDFDocument) buildHeader(page PDFPage) string {
	// Header includes document title and page numbering
	// Format: "Title - Page X of Y\n"
	return fmt.Sprintf("%s - Page %d of %d\n", doc.Title, page.PageNum, len(doc.Pages))
}

// ExportWithWatermark adds a watermark and exports
func (doc *PDFDocument) ExportWithWatermark(w io.Writer, watermark string) error {
	doc.SetMetadata("watermark", watermark)
	log.Printf("Exporting document '%s' with watermark", doc.Title)
	return doc.GeneratePDF(w)
}
